// Logos of the integrations catalog (web/scripts/integration-logos.mjs, generated by npm run logos).
import assert from 'node:assert/strict';
import test from 'node:test';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { OUT as BRAND_ICONS, sanitizeSvg } from '../web/scripts/fetch-brand-icons.mjs';
import { catalogLogoKeys, isGeneric, logoExists, resolveLogo } from '../web/scripts/integration-logos.mjs';
import { BRAND_LOGOS } from '../web/src/assets/brandLogos.generated.ts';
import { INTEGRATION_LOGOS } from '../web/src/assets/integrationLogos.generated.ts';

const keys = catalogLogoKeys();
const byId = new Map(keys.map((k) => [k.id, k]));
const logoOf = (id) => resolveLogo(byId.get(id) ?? assert.fail(`${id} is in the catalog`));

test('well-known integrations show their own brand', () => {
  const expected = {
    clickhouse: 'si:clickhouse',
    cockroachdb: 'si:cockroachlabs',
    couchdb: 'logos:couchdb-icon',
    cilium: 'si:cilium',
    linkerd: 'logos:linkerd',
    'traefik-mesh': 'si:traefikproxy',
    argocd: 'logos:argo-icon',
    keycloak: 'si:keycloak',
    kong: 'logos:kong-icon',
    flink: 'si:apacheflink',
    nifi: 'si:apachenifi',
    solr: 'logos:solr',
    hive: 'si:apachehive',
    zookeeper: 'logos:apache',
    pulsar: 'si:apachepulsar',
    druid: 'si:apachedruid',
    yarn: 'si:apachehadoop',
    'hdfs-namenode': 'si:apachehadoop',
    jmeter: 'si:apachejmeter',
    openshift: 'si:redhatopenshift',
    vsphere: 'logos:vmware',
    fluentd: 'si:fluentd',
    supabase: 'logos:supabase-icon',
    'snmp-cisco': 'si:cisco',
    'cisco-asa': 'si:cisco',
    'kube-scheduler': 'logos:kubernetes',
    'windows-service': 'logos:microsoft-windows-icon',
    'okta-workflows': 'logos:okta-icon',
    'crowdstrike-fdr': 'brand:crowdstrike',
    'zscaler-private-access': 'brand:zscaler',
    keda: 'brand:keda',
    haproxy: 'brand:haproxy',
    'aws-applicationelb': 'cloud:aws/aws-applicationelb',
    'aws-kafka': 'cloud:aws/aws-kafka',
    'aws-states': 'cloud:aws/aws-states',
    'aws-appstream': 'logos:aws',
    'aws-billing': 'cloud:aws/aws-billing',
    'gcp-bigquery': 'cloud:gcp/gcp-bigquery',
    'gcp-pubsub': 'cloud:gcp/gcp-pubsub',
    'gcp-gke': 'cloud:gcp/gcp-gke',
    'azure-compute-virtualmachines': 'cloud:azure/azure-compute-virtualmachines',
  };
  for (const [id, logo] of Object.entries(expected)) assert.equal(logoOf(id), logo, id);
});

test('Datadog’s own agents and generic host checks never get a third-party brand', () => {
  for (const id of ['datadog-agent', 'datadog-cluster-agent', 'datadog-operator', 'disk', 'network', 'process', 'battery', 'directory', 'tls', 'ntp', 'dns', 'ssh', 'thermal', 'container'])
    assert.equal(logoOf(id), null, id);
});

test('every logo the resolver names exists in its icon set', () => {
  for (const k of keys) {
    const logo = resolveLogo(k);
    if (logo) assert.ok(logoExists(logo), `${k.id}: ${logo}`);
  }
});

/** Brands with no logo we can use yet: neither icon set has them and their sites serve no icon we can fetch. */
const WITHOUT_LOGO = [
  'aimon',
  'appgate-sdp',
  'cato-networks',
  'cybersixgill-actionable-alerts',
  'kyoto-tycoon',
  'lambdatest',
  'resin',
  'scaphandre',
  'supervisord',
  'tokumx',
  'twemproxy',
  'vertica',
  'ziris',
];

test('every branded catalog integration has its logo', () => {
  const missing = keys.filter((k) => !isGeneric(k.id) && !resolveLogo(k)).map((k) => k.id);
  assert.deepEqual([...new Set(missing)].sort(), WITHOUT_LOGO);
});

test('downloaded SVGs carry no scripts, handlers or external references', () => {
  assert.equal(
    sanitizeSvg('<?xml version="1.0"?><svg onload="x()"><script>x()</script><a href="https://e.com"><path d="M0"/></a><use xlink:href="#a"/></svg>'),
    '<svg><a><path d="M0"/></a><use xlink:href="#a"/></svg>',
  );
  // Editor metadata (Inkscape, Sketch) loses its namespace declarations once the logo is rewrapped.
  assert.equal(
    sanitizeSvg('<svg inkscape:version="1"><sodipodi:namedview id="n" /><inkscape:grid></inkscape:grid><path sodipodi:type="arc" xml:space="preserve" d="M0"/></svg>'),
    '<svg><path xml:space="preserve" d="M0"/></svg>',
  );
  const notice = readFileSync(new URL('NOTICE.md', BRAND_ICONS), 'utf8');
  for (const file of readdirSync(BRAND_ICONS).filter((f) => f !== 'NOTICE.md')) {
    assert.ok(notice.includes(`| \`${file}\` |`), `NOTICE.md lists ${file}`);
    if (file.endsWith('.svg')) assert.equal(sanitizeSvg(readFileSync(new URL(file, BRAND_ICONS), 'utf8')), readFileSync(new URL(file, BRAND_ICONS), 'utf8').trim(), `${file} is sanitized`);
  }
  assert.ok(existsSync(BRAND_ICONS));
});

test('the generated logos cover every catalog key that resolves', () => {
  for (const k of keys) if (resolveLogo(k)) assert.ok(BRAND_LOGOS[k.key] ?? INTEGRATION_LOGOS[k.key], `${k.key}: run npm run logos`);
  for (const file of new Set(Object.values(INTEGRATION_LOGOS))) assert.ok(existsSync(new URL(`../web/public/images/integrations/logos/${file}`, import.meta.url)), `${file}: run npm run logos`);
});
